function get_max_sum(n){
    if(n === 0 || n === 1){
        return n;
    }
    const half = Math.floor(n / 2);
    const third = Math.floor(n / 3);
    const fourth = Math.floor(n / 4);
    const fifth = Math.floor(n / 5);

    return Math.max(get_max_sum(half) + get_max_sum(third) + get_max_sum(fourth) + get_max_sum(fifth), n);
}

