function find_First_Missing(array){
  let start = 0, end = array.length - 1;

  while (start <= end) {
    let mid = Math.floor((start + end) / 2);

    // If the element at the middle index is equal to the index, it means the missing number lies in the right half
    if (array[mid] === mid) {
      start = mid + 1;
    } else {
      // If the element at the middle index is not equal to the index, it means the missing number lies in the left half
      end = mid - 1;
    }
  }

  // The first index where the element is not equal to its index is the first missing number
  return start;
}

