function is_nested(string) {
    let depth = 0;
    let hasNested = false;

    for (let i = 0; i < string.length; i++) {
        if (string[i] === '[') {
            depth++;
            if (depth > 1 && !hasNested) {
                hasNested = true;
            }
        } else if (string[i] === ']') {
            depth--;
            if (depth < 0) {
                return false; // A closing bracket without a matching opening bracket
            }
            if (depth === 0 && hasNested) {
                return true; // Found a nested subsequence
            }
        }
    }

    return false;
}

