function sequence(n) {
  let cache = new Map();

  function find(n) {
    if (n <= 0) {
      return 0;
    }
    if (n <= 2) {
      return 1;
    }
    if (cache.has(n)) {
      return cache.get(n);
    }
    const a = find(Math.floor((n + 1) / 2));
    const b = find(n - Math.floor((n + 1) / 2));
    const result = a + b;
    cache.set(n, result);
    return result;
  }

  return find(n);
}

