function pancake_sort(nums) {
    let n = nums.length;
    for (let i = n - 1; i > 0; i--) {
        // Find the index of the maximum element in nums[0..i]
        let maxIndex = i;
        for (let j = 0; j < i; j++) {
            if (nums[j] > nums[maxIndex]) {
                maxIndex = j;
            }
        }
        // Move the maximum element to the end of the array
        if (maxIndex !== i) {
            // Reverse the array from 0 to maxIndex
            reverse(nums, 0, maxIndex);
            // Reverse the entire array from 0 to i
            reverse(nums, 0, i);
        }
    }
    return nums;
}

function reverse(nums, start, end) {
    while (start < end) {
        let temp = nums[start];
        nums[start] = nums[end];
        nums[end] = temp;
        start++;
        end--;
    }
}

function pancake_sort(nums) {
    function flip(subArray, k) {
        let start = 0;
        let end = k;
        while (start < end) {
            let temp = subArray[start];
            subArray[start] = subArray[end];
            subArray[end] = temp;
            start++;
            end--;
        }
    }

    let n = nums.length;
    for (let i = n; i > 1; i--) {
        // Find the index of the maximum element in nums[0..i-1]
        let maxIndex = nums.indexOf(Math.max(...nums.slice(0, i)));

        // Move the maximum element to end of current array if it's not already at the end
        if (maxIndex !== i - 1) {
            // First move the maximum number to the beginning
            flip(nums, maxIndex);
            // Now move the maximum number to its correct position
            flip(nums, i - 1);
        }
    }
    return nums;
}

