function max_product(arr) {
    if (arr.length === 0) return 0;

    let maxProduct = arr[0];
    for (let i = 0; i < arr.length; i++) {
        let currentProduct = arr[i];
        for (let j = i + 1; j < arr.length; j++) {
            if (arr[j] > arr[j - 1]) {
                currentProduct *= arr[j];
                maxProduct = Math.max(maxProduct, currentProduct);
            } else {
                break;
            }
        }
    }
    return maxProduct;
}

function toggle_middle_bits(n) {
    // Calculate the number of bits in the number
    let numBits = n.toString(2).length;

    // If there are less than 3 bits, no middle bits to toggle
    if (numBits <= 2) {
        return n;
    }

    // Create a mask to toggle bits except the first and last
    let mask = 0;
    for (let i = 1; i < numBits - 1; i++) {
        mask |= (1 << i);
    }

    // Toggle the middle bits
    return n ^ mask;
}

