    let prev = lst[0];

    for (let i = 1; i < lst.length; i++) {
        if (lst[i] < prev) {
            sorted = false;
            break;
        }
        prev = lst[i];
    }

    // Check for more than one duplicate of the same number
    for (let i = 1; i < lst.length; i++) {
        if (lst[i] === lst[i - 1]) {
            if (lst.indexOf(lst[i], i + 1) !== -1) {
                return false;
            }
        }
    }

    return sorted;
}

