    const uniqueNumbers = [...new Set(numbers)];

    // Sort the unique numbers in ascending order
    uniqueNumbers.sort((a, b) => a - b);

    // Check if the array has at least two elements to determine the second smallest
    if (uniqueNumbers.length >= 2) {
        return uniqueNumbers[1];
    } else {
        // Return null if there are not enough unique numbers to find a second smallest
        return null;
    }
}

