function max_fill(grid, capacity) {
  let totalSteps = 0;
  for (let row of grid) {
    let waterUnits = row.reduce((acc, val) => acc + val, 0);
    totalSteps += Math.ceil(waterUnits / capacity);
  }
  return totalSteps;
}

