  let spaceCount = 0;

  for (let i = 0; i < text.length; i++) {
    if (text[i] === ' ') {
      spaceCount++;
    } else {
      if (spaceCount > 2) {
        result += '-';
      } else {
        result += '_'.repeat(spaceCount);
      }
      spaceCount = 0;
      result += text[i];
    }
  }

  // Handle trailing spaces
  if (spaceCount > 2) {
    result += '-';
  } else {
    result += '_'.repeat(spaceCount);
  }

  return result;
}

