function fib4(n){
  let fib = [0, 0, 2, 0]; // Initialize the first four elements of the fib4 sequence
  for (let i = 4; i <= n; i++) {
    fib[i] = fib[i-1] + fib[i-2] + fib[i-3] + fib[i-4]; // Compute the next element
  }
  return fib[n]; // Return the n-th element of the fib4 sequence
}

