function max_sum(arr) {
  // Initialize an array to store the maximum sum of increasing subsequence ending at each index
  const inc = new Array(arr.length).fill(0);
  // Initialize an array to store the maximum sum of decreasing subsequence starting at each index
  const dec = new Array(arr.length).fill(0);

  // Calculate maximum sum of increasing subsequence ending at each index
  for (let i = 0; i < arr.length; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && inc[j] + arr[i] > inc[i]) {
        inc[i] = inc[j] + arr[i];
      }
    }
    if (inc[i] === 0) {
      inc[i] = arr[i];
    }
  }

  // Calculate maximum sum of decreasing subsequence starting at each index
  for (let i = arr.length - 1; i >= 0; i--) {
    for (let j = arr.length - 1; j >= i; j--) {
      if (arr[i] > arr[j] && dec[j] + arr[i] > dec[i]) {
        dec[i] = dec[j] + arr[i];
      }
    }
    if (dec[i] === 0) {
      dec[i] = arr[i];
    }
  }

  // Calculate the maximum sum of bitonic subsequence
  let max_bitonic = 0;
  for (let i = 0; i < arr.length; i++) {
    max_bitonic = Math.max(max_bitonic, inc[i] + dec[i] - arr[i]);
  }

  return max_bitonic;
}

