function search(arr){
    let left = 0;
    let right = arr.length - 1;

    while (left < right) {
        let mid = Math.floor((left + right) / 2);

        // If the middle element is even, the single element could be in the right half
        if (mid % 2 === 0) {
            if (arr[mid] === arr[mid + 1]) {
                left = mid + 2; // Move to the right half
            } else {
                right = mid; // Move to the left half
            }
        } else {
            // If the middle element is odd, the single element could be in the left half
            if (arr[mid] === arr[mid + 1]) {
                right = mid - 2; // Move to the left half
            } else {
                left = mid + 1; // Move to the right half
            }
        }
    }

    // When left and right converge, arr[left] is the single element
    return arr[left];
}

