function pancake_sort(nums) {
    function flip(nums, start, end) {
        while (start < end) {
            [nums[start], nums[end]] = [nums[end], nums[start]];
            start++;
            end--;
        }
    }

    for (let size = nums.length; size > 1; size--) {
        let maxIndex = 0;
        for (let i = 1; i < size; i++) {
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
        }

        flip(nums, 0, maxIndex);
        flip(nums, 0, size - 1);
    }

    return nums;
}

function pancake_sort(nums) {
  function flip(nums, index) {
    let start = 0;
    let end = index;
    while (start < end) {
      let temp = nums[start];
      nums[start] = nums[end];
      nums[end] = temp;
      start++;
      end--;
    }
  }

  for (let size = nums.length; size > 1; size--) {
    let maxIndex = 0;
    for (let i = 1; i < size; i++) {
      if (nums[i] > nums[maxIndex]) {
        maxIndex = i;
      }
    }

    flip(nums, maxIndex);
    flip(nums, size - 1);
  }

  return nums;
}

