function is_sublist(l, s) {
  for (let i = 0; i <= l.length - s.length; i++) {
    let match = true;
    for (let j = 0; j < s.length; j++) {
      if (l[i + j] !== s[j]) {
        match = false;
        break;
      }
    }
    if (match) {
      return true;
    }
  }
  return false;
}

function is_sublist(l, s){
  // Check if the subarray is empty
  if (s.length === 0) return true;

  // Check if the main array is shorter than the subarray
  if (l.length < s.length) return false;

  // Iterate through the main array
  for (let i = 0; i <= l.length - s.length; i++) {
    // Check if the current slice of the main array matches the subarray
    if (l.slice(i, i + s.length).join(',') === s.join(',')) {
      return true;
    }
  }

  // If no match is found, return false
  return false;
}

