  let mergedDict = {};

  // Merge dict1 into mergedDict
  for (let key in dict1) {
    mergedDict[key] = dict1[key];
  }

  // Merge dict2 into mergedDict
  for (let key in dict2) {
    if (!mergedDict.hasOwnProperty(key)) {
      mergedDict[key] = dict2[key];
    }
  }

  // Merge dict3 into mergedDict
  for (let key in dict3) {
    if (!mergedDict.hasOwnProperty(key)) {
      mergedDict[key] = dict3[key];
    }
  }

  return mergedDict;
}

