function amicable_numbers_sum(limit) {
  function sumOfDivisors(n) {
    let sum = 1; // Start with 1 because it's a divisor for all numbers
    for (let i = 2; i <= Math.sqrt(n); i++) {
      if (n % i === 0) {
        sum += i;
        if (i !== n / i) {
          sum += n / i;
        }
      }
    }
    return sum;
  }

  let sum = 0;
  for (let i = 2; i <= limit; i++) {
    let a = sumOfDivisors(i);
    let b = sumOfDivisors(a);
    if (i === b && i !== a) {
      sum += i;
    }
  }
  return sum;
}

