                sum += i;
                if (i !== n / i) {
                    sum += n / i;
                }
            }
        }
        return sum;
    }

    let amicableSum = 0;
    for (let i = 2; i < limit; i++) {
        let sum1 = sum_of_divisors(i);
        let sum2 = sum_of_divisors(sum1);
        if (i !== sum1 && i === sum2) {
            amicableSum += i;
        }
    }
    return amicableSum;
}

