    if (n === 0) return 1;
    if (n === 1) return 1;

    let bell = new Array(n + 1).fill(0);
    bell[0] = 1;
    bell[1] = 1;

    for (let i = 2; i <= n; i++) {
        bell[i] = 0;
        for (let j = 0; j < i; j++) {
            bell[i] += bell[j] * factorial(i - j - 1);
        }
    }

    function factorial(x) {
        let result = 1;
        for (let i = 2; i <= x; i++) {
            result *= i;
        }
        return result;
    }

    return bell[n];
}

function bell_Number(n) {
    // Initialize a 2D array to store Bell numbers
    let Bell = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));

    // The first Bell number is 1
    Bell[0][0] = 1;

    // Fill the Bell triangle
    for (let i = 1; i <= n; i++) {
        Bell[i][0] = Bell[i - 1][i - 1];

        for (let j = 1; j <= i; j++) {
            Bell[i][j] = Bell[i - 1][j - 1] + Bell[i][j - 1];
        }
    }

    // The nth Bell number is in the nth row, 0th column
    return Bell[n][0];
}

