function search(arr) {
  let start = 0;
  let end = arr.length - 1;

  while (start <= end) {
    const mid = Math.floor((start + end) / 2);

    if ((mid === 0 || arr[mid] !== arr[mid - 1]) && (mid === arr.length - 1 || arr[mid] !== arr[mid + 1])) {
      return arr[mid];
    } else if (arr[mid] === arr[mid - 1]) {
      if (mid % 2 === 0) {
        end = mid - 2;
      } else {
        start = mid + 1;
      }
    } else {
      if (mid % 2 === 0) {
        start = mid + 1;
      } else {
        end = mid - 2;
      }
    }
  }

  throw new Error("No unique element found");
}

