function rgb_to_hsv(r, g, b) {
    r /= 255;
    g /= 255;
    b /= 255;

    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let hue;
    if (delta === 0) {
        hue = 0;
    } else if (max === r) {
        hue = 60 * ((g - b) / delta);
    } else if (max === g) {
        hue = 60 * ((b - r) / delta) + 120;
    } else {
        hue = 60 * ((r - g) / delta) + 240;
    }

    hue = hue % 360;

    let saturation;
    if (max === 0) {
        saturation = 0;
    } else {
        saturation = (delta / max) * 100;
    }

    let value = max * 100;

    return [hue, saturation, value];
}

