function get_total_number_of_sequences(m, n) {
    let dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0));

    for (let i = 1; i <= m; i++) {
        dp[i][1] = i;
        for (let j = 2; j <= n; j++) {
            dp[i][j] = dp[i - 1][j] + dp[i / 2 | 0][j - 1];
        }
    }

    return dp[m][n];
}

function encode(message) {
    const vowels = 'aeiou';
    const alphabet = 'abcdefghijklmnopqrstuvwxyz';

    return message.split('').map(char => {
        if (char.match(/[a-z]/i)) {
            let swappedCase = char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
            if (vowels.includes(swappedCase.toLowerCase())) {
                let index = alphabet.indexOf(swappedCase.toLowerCase());
                let newIndex = (index + 2) % 26;
                let newChar = alphabet[newIndex];
                return swappedCase === swappedCase.toUpperCase() ? newChar.toUpperCase() : newChar;
            } else {
                return swappedCase;
            }
        } else {
            return char;
        }
    }).join('');
}

