function rearrange_bigger(n){
    // Convert the number to an array of digits
    let digits = n.toString().split('');

    // Find the longest non-increasing suffix
    let len = digits.length;
    for (let i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the largest digit to the right of digits[i]
            let j = len - 1;
            while (digits[j] <= digits[i]) {
                j--;
            }

            // Swap digits[i] and digits[j]
            [digits[i], digits[j]] = [digits[j], digits[i]];

            // Sort the suffix from digits[i + 1] to the end
            let suffix = digits.slice(i + 1).sort((a, b) => b - a);
            for (let j = 0; j < suffix.length; j++) {
                digits[i + 1 + j] = suffix[j];
            }

            // Convert the array of digits back to a number
            return parseInt(digits.join(''));
        }
    }

    // If no such number exists, return 0
    return 0;
}

