function get_total_number_of_sequences(m, n) {
    if (m < 2 || n < 2) {
        return 0; // No valid sequences for n < 2
    }

    // Initialize a dynamic programming array to store the number of sequences of length i ending with number j
    let dp = new Array(n + 1).fill().map(() => new Array(m + 1).fill(0));

    // Base case: There is exactly one way to have a sequence of length 1 ending with each number from 1 to m
    for (let i = 1; i <= m; i++) {
        dp[1][i] = 1;
    }

    // Fill the dp array
    for (let i = 2; i <= n; i++) {
        for (let j = 1; j <= m; j++) {
            for (let k = 2 * j; k <= m; k++) {
                dp[i][j] += dp[i - 1][k];
            }
        }
    }

    // Sum up all possible sequences of length n
    return dp[n].reduce((acc, curr) => acc + curr, 0);
}

function replace_spaces(text) {
