function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        dp[i] = a[i];
    }
    for (let i = 0; i <= index; i++) {
        for (let j = i + 1; j <= k; j++) {
            if (a[j] > a[i] && dp[j] < dp[i] + a[j]) {
                dp[j] = dp[i] + a[j];
            }
        }
    }
    return dp[k];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const pq = new PriorityQueue((a, b) => {
        for (let i = 0; i < k; i++) {
            if (a.path[i] !== b.path[i]) return a.path[i] - b.path[i];
        }
        return 0;
    });

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            pq.enqueue({ path: [grid[i][j]], x: i, y: j });
        }
    }

    while (!pq.isEmpty()) {
        const { path, x, y } = pq.dequeue();
        if (path.length === k) return path;
        for (const [dx, dy] of directions) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N) {
                pq.enqueue({ path: [...path, grid[nx][ny]], x: nx, y: ny });
            }
        }
    }
}

// Priority Queue implementation
class PriorityQueue {
    constructor(comparator = (a, b) => a - b) {
        this.values = [];
        this.comparator = comparator;
    }

    enqueue(value) {
        this.values.push(value);
        this.values.sort(this.comparator);
    }

    dequeue() {
        return this.values.shift();
    }

    isEmpty() {
        return this.values.length === 0;
    }
}

