function is_prime(num) {
  if (num <= 1) return false;
  if (num <= 3) return true;
  if (num % 2 === 0 || num % 3 === 0) return false;
  for (let i = 5; i * i <= num; i += 6) {
    if (num % i === 0 || num % (i + 2) === 0) return false;
  }
  return true;
}

function newman_number(i) {
  if (i === 1) return 1;
  if (i === 2) return 2;
  let a = 1, b = 1;
  for (let j = 3; j <= i; j++) {
    let temp = a;
    a = b;
    b = temp + 2 * b;
  }
  return a;
}

