function max_Product(arr){
  if (arr.length < 2) {
    return null; // Not enough elements to form a product
  }

  // Initialize variables to store the maximum product and its corresponding pair
  let maxProduct = arr[0] * arr[1];
  let maxPair = [arr[0], arr[1]];

  // Iterate through the array to find the pair with the maximum product
  for (let i = 1; i < arr.length - 1; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      let product = arr[i] * arr[j];
      if (product > maxProduct) {
        maxProduct = product;
        maxPair = [arr[i], arr[j]];
      }
    }
  }

  return maxPair;
}

